// Test script for the POST /check endpoint
const axios = require('axios');

async function testCheckEndpoint() {
  const baseUrl = 'http://localhost:3000';

  console.log('Testing POST /check endpoint...\n');

  // Test 1: Valid rule with context
  console.log('Test 1: Valid rule with context');
  try {
    const response1 = await axios.post(`${baseUrl}/check`, {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    });
    console.log('Response:', response1.data);
    console.log('Expected: { result: true }');
  } catch (error) {
    console.log('Error:', error.response?.data || error.message);
  }

  console.log('\n---\n');

  // Test 2: Valid rule with false result
  console.log('Test 2: Valid rule with false result');
  try {
    const response2 = await axios.post(`${baseUrl}/check`, {
      rule: 'ctx.amount > 100',
      context: { amount: 50 }
    });
    console.log('Response:', response2.data);
    console.log('Expected: { result: false }');
  } catch (error) {
    console.log('Error:', error.response?.data || error.message);
  }

  console.log('\n---\n');

  // Test 3: Missing rule
  console.log('Test 3: Missing rule');
  try {
    const response3 = await axios.post(`${baseUrl}/check`, {
      context: { amount: 150 }
    });
    console.log('Response:', response3.data);
  } catch (error) {
    console.log('Error status:', error.response?.status);
    console.log('Error data:', error.response?.data);
  }

  console.log('\n---\n');

  // Test 4: Invalid rule syntax
  console.log('Test 4: Invalid rule syntax');
  try {
    const response4 = await axios.post(`${baseUrl}/check`, {
      rule: 'ctx.amount >',
      context: { amount: 150 }
    });
    console.log('Response:', response4.data);
  } catch (error) {
    console.log('Error status:', error.response?.status);
    console.log('Error data:', error.response?.data);
  }

  console.log('\n---\n');

  // Test 5: Rule using request properties
  console.log('Test 5: Rule using request properties');
  try {
    const response5 = await axios.post(`${baseUrl}/check`, {
      rule: 'req.method === "POST" && ctx.value === "test"',
      context: { value: 'test' }
    });
    console.log('Response:', response5.data);
    console.log('Expected: { result: true }');
  } catch (error) {
    console.log('Error:', error.response?.data || error.message);
  }
}

// Check if axios is available
try {
  require.resolve('axios');
  testCheckEndpoint();
} catch (e) {
  console.log('To run this test, install axios first:');
  console.log('npm install axios');
}

// Quick test to verify the implementation
const app = require('./app.js');
const supertest = require('supertest');
const request = supertest(app);

async function runTests() {
  console.log('Testing POST /check endpoint implementation...\n');

  // Test 1: Basic rule evaluation
  console.log('Test 1: Basic rule evaluation (ctx.amount > 100)');
  const response1 = await request
    .post('/check')
    .send({ rule: 'ctx.amount > 100', context: { amount: 150 } });
  console.log('Status:', response1.status);
  console.log('Body:', response1.body);
  console.log('Expected: 200, { result: true }\n');

  // Test 2: False result
  console.log('Test 2: False result (ctx.amount > 100)');
  const response2 = await request
    .post('/check')
    .send({ rule: 'ctx.amount > 100', context: { amount: 50 } });
  console.log('Status:', response2.status);
  console.log('Body:', response2.body);
  console.log('Expected: 200, { result: false }\n');

  // Test 3: Missing rule
  console.log('Test 3: Missing rule');
  const response3 = await request
    .post('/check')
    .send({ context: { amount: 150 } });
  console.log('Status:', response3.status);
  console.log('Body:', response3.body);
  console.log('Expected: 400, { error: "Missing rule expression" }\n');

  // Test 4: Complex rule
  console.log('Test 4: Complex rule');
  const response4 = await request
    .post('/check')
    .send({ 
      rule: 'ctx.user.age >= 18 && ctx.user.age <= 65 && ctx.transaction.amount < 5000',
      context: { 
        user: { age: 25, name: 'Alice' },
        transaction: { amount: 1000, currency: 'USD' }
      } 
    });
  console.log('Status:', response4.status);
  console.log('Body:', response4.body);
  console.log('Expected: 200, { result: true }\n');

  console.log('All tests completed!');
  process.exit(0);
}

// Check if supertest is available
try {
  require.resolve('supertest');
  runTests();
} catch (e) {
  console.log('To run the full test, install supertest first:');
  console.log('npm install supertest');
  console.log('\nAlternatively, you can test with curl:');
  console.log('./test_curl.sh');
}

