// Simple test script for the /check endpoint

const app = require('./app');
const request = require('supertest');

// Test 1: Basic rule evaluation
async function testBasicRule() {
  console.log('Test 1: Basic rule evaluation');

  const response = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    })
    .expect('Content-Type', /json/);

  console.log('Response:', response.body);
  console.log('Expected result: true, Got:', response.body.result);
  console.log('---');
}

// Test 2: Rule with request context
async function testRuleWithRequest() {
  console.log('Test 2: Rule with request context');

  // This would test accessing req properties in the rule
  // Note: In the actual Function() call, 'req' is the request object
  const response = await request(app)
    .post('/check')
    .set('X-User-Id', '123')
    .send({
      rule: 'ctx.userId === "123" && req.get("X-User-Id") === "123"',
      context: { userId: '123' }
    })
    .expect('Content-Type', /json/);

  console.log('Response:', response.body);
  console.log('---');
}

// Test 3: Missing rule field
async function testMissingRule() {
  console.log('Test 3: Missing rule field');

  const response = await request(app)
    .post('/check')
    .send({
      context: { amount: 50 }
    })
    .expect(400);

  console.log('Response:', response.body);
  console.log('---');
}

// Test 4: Invalid rule expression
async function testInvalidRule() {
  console.log('Test 4: Invalid rule expression');

  const response = await request(app)
    .post('/check')
    .send({
      rule: 'ctx.amount >', // Invalid syntax
      context: { amount: 50 }
    })
    .expect(400);

  console.log('Response:', response.body);
  console.log('---');
}

// Run tests
async function runTests() {
  console.log('Starting tests for POST /check endpoint\n');

  try {
    // Start the server
    const server = app.listen(3001, async () => {
      console.log('Test server running on port 3001');

      try {
        await testBasicRule();
        await testRuleWithRequest();
        await testMissingRule();
        await testInvalidRule();

        console.log('All tests completed!');
      } catch (error) {
        console.error('Test error:', error);
      } finally {
        server.close();
        process.exit(0);
      }
    });
  } catch (error) {
    console.error('Server error:', error);
    process.exit(1);
  }
}

// Check if we're running directly
if (require.main === module) {
  // Note: supertest requires the app to be exported
  console.log('To run these tests, install supertest first:');
  console.log('npm install supertest');
  console.log('\nThen run: node test_check_endpoint.js');
} else {
  runTests();
}

