  }
};
try {
  const result3 = evalRuleSimulated(testReq3);
  console.log(`Context: ${JSON.stringify(testReq3.body.context)}`);
  console.log(`Result: ${result3} (expected: true)`);
  console.log('✓ Test passed\n');
} catch (error) {
  console.log(`✗ Error: ${error.message}\n`);
}

