#!/usr/bin/env node

// Test script for the POST /check endpoint

const http = require('http');

const testData = {
  // Test 1: Simple numeric comparison
  test1: {
    rule: 'ctx.amount > 100',
    context: { amount: 150 }
  },
  // Test 2: String comparison
  test2: {
    rule: 'ctx.user === "admin"',
    context: { user: 'admin' }
  },
  // Test 3: Complex expression
  test3: {
    rule: 'ctx.age >= 18 && ctx.hasLicense === true',
    context: { age: 25, hasLicense: true }
  },
  // Test 4: Using request properties
  test4: {
    rule: 'req.method === "POST"',
    context: {}
  },
  // Test 5: Accessing nested properties
  test5: {
    rule: 'ctx.user.role === "admin" && ctx.user.active',
    context: { user: { role: 'admin', active: true } }
  }
};

function makeRequest(testData, testName) {
  const data = JSON.stringify(testData);

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length
    }
  };

  console.log(`\n=== Testing: ${testName} ===`);
  console.log('Request:', testData);

  const req = http.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      console.log(`Status Code: ${res.statusCode}`);
      console.log('Response:', JSON.parse(responseData));
    });
  });

  req.on('error', (error) => {
    console.error(`Error in ${testName}:`, error.message);
  });

  req.write(data);
  req.end();
}

// Start the tests
console.log('Testing POST /check endpoint...');

// Test each case
setTimeout(() => makeRequest(testData.test1, 'Simple numeric comparison'), 500);
setTimeout(() => makeRequest(testData.test2, 'String comparison'), 1000);
setTimeout(() => makeRequest(testData.test3, 'Complex expression'), 1500);
setTimeout(() => makeRequest(testData.test4, 'Using request properties'), 2000);
setTimeout(() => makeRequest(testData.test5, 'Nested properties'), 2500);

// Test error case - missing rule
setTimeout(() => {
  console.log('\n=== Testing: Missing rule (should fail) ===');
  const errorData = JSON.stringify({ context: { amount: 100 } });

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': errorData.length
    }
  };

  const req = http.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      console.log(`Status Code: ${res.statusCode}`);
      console.log('Response:', JSON.parse(responseData));
    });
  });

  req.write(errorData);
  req.end();
}, 3000);

