  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

// Test cases
const testCases = [
  {
    name: 'Simple amount check (true)',
    req: {
      body: {
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      }
    },
    expected: true
  },
  {
    name: 'Simple amount check (false)',
    req: {
      body: {
        rule: 'ctx.amount > 100',
        context: { amount: 50 }
      }
    },
    expected: false
  },
  {
    name: 'Complex expression',
    req: {
      body: {
        rule: 'ctx.age >= 18 && ctx.country === "US"',
        context: { age: 21, country: "US" }
      }
    },
    expected: true
  },
  {
    name: 'Expression with req access',
    req: {
      method: 'POST',
      body: {
        rule: 'req.method === "POST" && ctx.userId === 123',
        context: { userId: 123 }
      }
    },
    expected: true
  },
  {
    name: 'Mathematical expression',
    req: {
      body: {
        rule: 'ctx.x * 2 > ctx.y + 10',
        context: { x: 15, y: 10 }
      }
    },
    expected: true // 15*2=30 > 10+10=20
  }
];

