// Simple test without external dependencies
const testRuleEngine = async () => {
  console.log('Testing rule engine implementation...\n');

  // Test 1: Basic rule evaluation
  console.log('Test 1: Basic rule evaluation (ctx.amount > 100)');
  const testServer = express();
  testServer.use(express.json());

  // Mock evalRule function
  const mockEvalRule = (req) => {
    const expr = req.body.rule;
    const ctx = { ctx: req.body.context, req };
    return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
  };

  testServer.post('/check', (req, res) => {
    try {
      if (!req.body.rule || !req.body.context) {
        return res.status(400).json({ error: 'Missing required fields' });
      }
      const result = mockEvalRule(req);
      res.json({ result: Boolean(result), evaluated: result });
    } catch (error) {
      res.status(400).json({ error: error.message });
    }
  });

  // Test cases
  const testCases = [
    {
      name: 'Simple numeric comparison',
      rule: 'ctx.amount > 100',
      context: { amount: 150 },
      expected: true
    },
    {
      name: 'String comparison',
      rule: 'ctx.user === "admin"',
      context: { user: 'admin' },
      expected: true
    },
    {
      name: 'Complex expression',
      rule: 'ctx.score > 80 && ctx.status === "active"',
      context: { score: 90, status: 'active' },
      expected: true
    },
    {
      name: 'False condition',
      rule: 'ctx.value < 0',
      context: { value: 10 },
      expected: false
    }
  ];

  for (const testCase of testCases) {
    const body = {
      rule: testCase.rule,
      context: testCase.context
    };

    // Simulate evaluation
    try {
      const mockReq = { body: body };
      const result = mockEvalRule(mockReq);
      const passed = Boolean(result) === testCase.expected;

      console.log(`  ${testCase.name}:`);
      console.log(`    Rule: ${testCase.rule}`);
      console.log(`    Context: ${JSON.stringify(testCase.context)}`);
      console.log(`    Expected: ${testCase.expected}, Got: ${Boolean(result)}`);
