const express = require('express');
const app = express();

// Middleware to parse JSON requests
app.use(express.json());

// Evaluate a caller-supplied rule expression against the request.
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.post('/check', (req, res) => {
  try {
    // Validate request body
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({
        error: 'Invalid request body',
        message: 'Request body must be a JSON object'
      });
    }

    if (!req.body.rule || typeof req.body.rule !== 'string') {
      return res.status(400).json({
        error: 'Missing required field',
        message: 'The "rule" field is required and must be a string'
      });
    }

    if (!req.body.context || typeof req.body.context !== 'object') {
      return res.status(400).json({
        error: 'Missing required field',
        message: 'The "context" field is required and must be an object'
      });
    }

    // Evaluate the rule
    const result = evalRule(req);

    // Return the evaluation result
    res.json({
      result: result,
      evaluated: true,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    // Handle evaluation errors
    res.status(400).json({
      error: 'Rule evaluation failed',
      message: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

