    },
    expected: { error: 'Missing required field' }
  },
  {
    name: 'Test 5: Missing context field',
    data: {
      rule: 'ctx.amount > 100'
    },
    expected: { error: 'Missing required field' }
  }
];

function sendRequest(testCase) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(testCase.data);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/check',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data)
      }
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        try {
          const result = JSON.parse(body);
          resolve({ status: res.statusCode, body: result });
        } catch (e) {
          resolve({ status: res.statusCode, body: body || 'No response body' });
        }
      });
    });

    req.on('error', (e) => {
      reject(e);
    });

    req.write(data);
    req.end();
  });
}

async function runTests() {
  console.log('Starting tests for POST /check endpoint...\n');

  for (const testCase of testData) {
    console.log(`Running: ${testCase.name}`);
    try {
      const response = await sendRequest(testCase);

      console.log(`  Status: ${response.status}`);
      console.log(`  Response: ${JSON.stringify(response.body, null, 2)}`);

      // Basic validation
      if (testCase.expected.error) {
